INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (31, 'zh-cn', '31', '', '单页测试2', '#333333', '', '', 'Admin', '本站', '', '2024-09-14 22:02:35', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 0, 0, 0, 'Admin', 'Admin', '2024-11-24 11:01:31', '2024-11-24 11:01:31', '4', '0', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (48, 'cn', '6', '', '环保行业网站模板', '', '', '', 'Admin', '', '', '2024-11-25 07:43:57', '/uploads/20250622/41d132cd2d284c5926635101aa2ac71f.jpeg', '', '', '<p>环保行业网站在当今数字化时代具有至关重要的作用，其重要性体现在多个方面。</p><p><img src=\"/storage/default/20241125/医疗网站缩略图(1)9da009ac88c5a129c9e579f016eb1b8bc203ad7b.jpg\" alt=\"医疗网站缩略图(1).jpg\" data-href=\"/storage/default/20241125/医疗网站缩略图(1)9da009ac88c5a129c9e579f016eb1b8bc203ad7b.jpg\" width=\"\" height=\"\" /></p><h3>（一）设计理念</h3><p>环保行业网站应遵循可持续设计原则，采用生态友好的设计理念。在色彩选择上，以清新自然的绿色为主色调，搭配蓝色、白色等辅助色彩，符合可持续发展概念。图标设计可采用循环箭头、绿色勾号、再生徽章等可持续发展相关的图标，突出环保主题，使网站在视觉上与众不同。同时，设计过程中应考虑网站的生命周期，确保其在使用过程中能够持续降低对环境的影响。例如，避免大面积使用深色背景，减少动画和视频的使用频率，以降低能源消耗。</p><p><br></p><h3>（二）节能优化</h3><p>能效优化是环保网站提升可持续性的重要手段。优化图片和多媒体文件的大小和格式，如使用现代的图像格式 WebP，能够在不损失质量的前提下减少文件大小，显著降低页面加载时间和服务器能源消耗。采用内容分发网络（CDN）技术，将网站内容分布到全球多个数据中心，减少用户访问的延迟和带宽消耗，提高用户体验的同时降低服务器的能源使用。选择绿色托管服务商也是关键一步，许多托管服务商已开始使用可再生能源为数据中心供电，有效减少网站的碳足迹。</p><p><br></p><h3>（三）可持续材料使用</h3><p>在网站建设中，可以选择可再生资源，如使用可再生能源供电、选择可再生材料制作硬件等。同时，资源循环利用也是实现可持续发展的重要途径，例如回收旧硬件、重复利用设计元素等，减少资源浪费。此外，通过选择高质量、耐用的硬件，减少硬件更换频率，可以有效减少电子垃圾的产生。</p><p><br></p><h3>（四）用户体验</h3><p>合理的导航和信息架构设计能帮助用户快速找到所需信息，减少不必要的点击和页面加载。响应式设计确保网站在各种设备上都能顺畅运行，提高用户满意度，减少因设备不兼容而产生的资源浪费。提供个性化和互动性的内容，增强用户的参与感和忠诚度。通过数据分析和用户反馈，不断优化网站功能和内容，提升整体用户体验。</p><p><br></p><h3>（五）内容管理</h3><p>网站内容应定期更新和优化，提供高质量的环保知识科普文章、视频和图片，以及及时发布环保新闻、报告等，确保内容的质量、准确性和实用性。使用内容管理系统（CMS），更高效地管理和更新网站内容。采用缓存技术减少服务器请求次数，提高网站加载速度，降低服务器负载和能源消耗。同时，对内容进行压缩与优化，如压缩图像、视频等多媒体文件，减少数据传输量，降低服务器负载和能耗。</p><p><br></p><h3>（六）社会责任</h3><p>环保网站不仅是技术平台，更是教育和意识提升的工具。通过设置专门的环保教育栏目，提供有关可持续发展的文章和资源，向用户传递环保知识和理念。设计在线活动或挑战赛，激励用户采取环保行动，如减少塑料使用或参与植树活动。还可以通过社交媒体传播环保成功案例和用户故事，扩大环保意识的影响力。积极与环保组织和专家合作，确保网站内容的科学性和权威性，为用户提供更准确和有用的环保信息。通过论坛和评论功能，鼓励用户分享经验和建议，形成积极的互动社区，提高用户参与度，为网站的持续改进提供宝贵反馈。跨行业合作也是推动环保网站设计创新的重要途径，与技术公司、教育机构和部门合作，获得更多资源和支持，共同推动可持续发展目标的实现。</p><p><br></p>', '', '', '', '环保行业网站在当今数字化时代具有至关重要的作用，其重要性体现在多个方面。（一）设计理念环保行业网站应遵循可持续设计原则，采用生态友好的设计理念。在色彩选择上，以清新自然的绿色为主色调，搭配蓝色、白色等辅助色彩，符合可持续发展概念。图标设计可采用循环箭头、绿色勾号、再生徽章等可持续发展相关的图标，突出', 256, '1', '0', '0', '0', 4, 0, 0, 'Admin', 'admin', '2024-11-25 08:02:29', '2025-06-22 18:41:17', '4', '', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (18, 'en', '38', '', 'tea', '#333333', '', '', '超级管理员', '本站', '', '2022-12-17 09:42:05', '', '', '', '<p>sdfsdf</p>', '', '', '', 'sdfsdf', 255, '1', '0', '0', '0', 1, 0, 0, 'admin', 'Admin', '2022-12-17 09:42:18', '2025-04-18 21:53:37', '4', '0', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (19, 'cn', '10', '', 'test', '#333333', '', '', '超级管理员', '本站', '', '2023-01-05 15:46:46', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 259, 0, 0, 'admin', 'admin', '2023-01-05 15:46:46', '2025-07-02 08:07:50', '4', '0', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (20, 'en', '13', '', '在线留言', '#333333', '', '', '超级管理员', '本站', '', '2023-01-05 20:21:52', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 1, 0, 0, 'admin', 'admin', '2023-01-05 20:21:52', '2024-09-04 20:37:12', '4', '0', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (60, 'cn', '9', '', '淘宝运营', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/bce882d6ddebc9f7e91248392e891fe0.jpeg', '/storage/default/20241126/teams4f3c94f4696e55452f157173f340e2d321252398a.jpeg,/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg', '', '<p><strong>岗位职责：</strong></p><p style=\"text-align:center\"><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\"/></p><p><br/></p><p>1、 负责平台运营的业务支撑工作，保证平台业务稳定发展；</p><p>2、 参与和优化部门业务操作流程，保证团队协同工作；</p><p>3、 为用户提供平台业务咨询服务；</p><p>4、 受理客户投诉，在授权范围内予以解决；</p><p>5、 网络活动视频录像与剪辑，挖掘优秀作品,后台信息简单编辑处理；</p><p>6、 与公司其他部门配合工作。</p><p style=\"text-align:center\"><img src=\"/storage/default/20241130/logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" alt=\"logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\"/></p><p><strong>任职要求：</strong></p><p>1、 专科及以上学历，热爱互联网行业；</p><p>2、 较强的工作责任心，踏实勤恳，积极向上，性格开朗；</p><p>3、 形象佳，口齿伶俐，普通话标准；</p><p>4、 熟练使用电脑，经常上网，会使用office等相关办公软件；</p><p>5、 能适应白班、夜班倒班工作制；</p><p>注：根据个人能力和特长，公司给予更多的发展及晋升空间。</p><p><br/></p><p><strong>工作地址：</strong>                        </p><h2>北京市朝阳区北苑路</h2>', '', '', '', '岗位职责：1、 负责平台运营的业务支撑工作，保证平台业务稳定发展；2、 参与和优化部门业务操作流程，保证团队协同工作；3、 为用户提供平台业务咨询服务；4、 受理客户投诉，在授权范围内予以解决；5、 网络活动视频录像与剪辑，挖掘优秀作品,后台信息简单编辑处理；6、 与公司其他部门配合工作。任职要求：1、 专科及以上...', 255, '1', '0', '0', '0', 4, 0, 0, 'Admin', 'test', '2024-11-26 07:26:42', '2025-06-27 15:41:27', '4', '', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (61, 'cn', '2', '', 'badoucms 正式上线1.0.0 版本', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d04eedf5fa381fbf8779592ad3783375.jpeg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p><img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\"/></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul class=\" list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>百度推送</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', 'badoucms,a,b', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表 区域管理（多语言） 模型管理（自定义内容模型） 模型字段管理（自定义', 1, '1', '0', '0', '0', 31, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-06-22 19:36:11', '4', '', '请先充值');
