INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (111, 'cn', '2', '33,34', 'badoucms 正式上线1.0.0 版本', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/0dcfaacfd8502183cd16ab3aad0475a3.png', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p>\r\n	<img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" />\r\n</p>\r\n<h3>\r\n	介绍\r\n</h3>\r\n<p>\r\n	BadouCMS 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。\r\n</p>\r\n<h3>\r\n	功能列表\r\n</h3>\r\n<ul class=\" list-paddingleft-2\">\r\n	<li>\r\n		<p>\r\n			区域管理（多语言）\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			模型管理（自定义内容模型）\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			模型字段管理（自定义模型字段）\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			栏目管理\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			内容管理（单页内容、文章内容、产品内容...自定义内容模型）\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			站点配置、公司信息\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			定制标签（自定义前台标签）\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			前台模版标签\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			轮播图片\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			多条件筛选\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			网站地图（sitemap）\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			友情链接\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			自定义表单\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			留言信息\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			文章内链\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			多条件搜索\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			百度推送\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			内容权限\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			会员字段\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			会员等级(设置栏目与内容浏览权限)\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			文章评论(回复、审核)\r\n		</p>\r\n	</li>\r\n	<li>\r\n		<p>\r\n			我的评论\r\n		</p>\r\n	</li>\r\n</ul>', 'badoucms,a,b', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表 区域管理（多语言） 模型管理（自定义内容模型） 模型字段管理（自定义', 1, '1', '0', '0', '0', 41, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-07-02 07:54:43', '4', '', '请先充值');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (112, 'cn', '2', '33,34', 'badoucms基于thinkphp8+vue3的网站管理系统', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br/></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><p ><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\"/></p><h3>功能列表</h3><ul class=\" list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>百度推送</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', 'cms', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表 区域管理（多语言） 模型管理（自定义内容模型） 模型字段管理（自定义', 2, '1', '0', '0', '0', 9, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-06-27 09:05:05', '4', '', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (113, 'cn', '2', '', 'badoucms 模板标签', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul><li> 区域管理（多语言）</li><li> 模型管理（自定义内容模型）</li><li> 模型字段管理（自定义模型字段）</li><li> 栏目管理</li><li> 内容管理（单页内容、文章内容、产品内容...自定义内容模型）</li><li> 站点配置、公司信息</li><li> 定制标签（自定义前台标签）</li><li> 前台模版标签</li><li> 轮播图片</li><li> 多条件筛选</li><li> 网站地图（sitemap）</li><li> 友情链接</li><li> 自定义表单</li><li> 留言信息</li><li> 文章内链</li><li> 多条件搜索</li><li> 百度推送</li><li> 内容权限</li><li> 会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</li><li> 会员字段</li><li> 会员等级(设置栏目与内容浏览权限)</li><li> 文章评论(回复、审核)</li><li> 我的评论</li></ul>', '', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表 区域管理（多语言） 模型管理（自定义内容模型） 模型字段管理（自定义', 4, '1', '0', '0', '0', 8, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-06-22 19:35:41', '4', '', '');
INSERT INTO `bd_cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`) VALUES (114, 'cn', '2', '', 'BadouCMS快速入门', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br/></p><p><br/></p><h2>图片缩放函数：resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>参数：$src_image=源图片路径 （必填）</p><p>$max_width=缩放后的宽度</p><p>$max_height=缩放后的高度</p><p>$img_quality=图片质量</p><p>在标签中使用：<code>{$item.ico|resize_img=&#39;10&#39;,&#39;10&#39;}</code></p>', 'wy', '', '', '测试新闻1', 255, '1', '0', '0', '0', 54, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-06-22 19:35:41', '4', '', '');
